37	bool IntersectFile::init() {
38	
39		_queryFRM = upCast(_context)->getFile(upCast(_context)->getQueryFileIdx());
40	
41		 if (upCast(_context)->getSortedInput()) {
42			 makeSweep();
43			return _sweep->init();
44		 } else {
45			_binTree = new BinTree( upCast(_context));
46			_binTree->loadDB();
47		 }
48	
49		 return true;
