52	bool IntersectFile::findNext(RecordKeyVector &hits)
53	{
54		 bool retVal = false;
55		 if (upCast(_context)->getSortedInput()) {
56			retVal = nextSortedFind(hits);
57		 } 
58		 else {
59			retVal = nextUnsortedFind(hits);
60		 }
61	
62		 if (retVal) {
63			 checkSplits(hits);
64		 }
65		 return retVal;
66	}
