120	void IntersectFile::checkSplits(RecordKeyVector &hitSet)
121	{
122		if (upCast(_context)->getObeySplits()) {
123			RecordKeyVector keySet(hitSet.getKey());
124			RecordKeyVector resultSet(hitSet.getKey());
125			upCast(_context)->getSplitBlockInfo()->findBlockedOverlaps(keySet, hitSet, resultSet);
126			hitSet.swap(resultSet);
127		}
128	}
