79	void BlockMgr::getBlocksFromBam(RecordKeyVector &keyList, bool &mustDelete)
80	{
81		const BamRecord *keyRecord = static_cast<const BamRecord *>(keyList.getKey());
82		const vector<BamTools::CigarOp> &cigarData = keyRecord->getCigarData();
83		CHRPOS currPos = keyRecord->getStartPos();
84		CHRPOS blockLength = 0;
85	
86		for (int i=0; i < (int)cigarData.size(); i++) {
87			char opType = cigarData[i].Type;
88			int opLen = (int)(cigarData[i].Length);
89	
90			switch(opType) {
91			case 'I':
92			case 'S':
93			case 'P':
94			case 'H':
95				break;
96			case 'M': case 'X': case '=':
97				blockLength += opLen;
98				break;
99			case 'D':
100			case 'N' :
101				if ((opType == 'D' && !_breakOnDeletionOps) ||
102						(opType == 'N' && !_breakOnSkipOps)) {
103					blockLength += opLen;
104				} else {
105					keyList.push_back(allocateAndAssignRecord(keyRecord, currPos, currPos + blockLength));
106					currPos += opLen + blockLength;
107					blockLength = 0;
108				}
109				break;
110			default:
111				fprintf(stderr, "ERROR: Found invalid Cigar operation: %c.\n", opType);
112				exit(1);
113				break;
114			}
115		}
116		if (blockLength > 0) {
117			keyList.push_back(allocateAndAssignRecord(keyRecord, currPos, currPos + blockLength));
118		}
119		mustDelete = true;
120	}
