if (getObeySplits()) {
	_splitBlockInfo = new BlockMgr(_overlapFractionA, _reciprocalFraction);
	// For a plain intersect the -f fraction is a property of the whole A
	// record, so a discontinuous (split) A record satisfies it when its
	// combined overlapping blocks do, not only when a single B record alone
	// covers that fraction of A. Other tools (e.g. coverage) evaluate the
	// fraction per overlapping record, so they keep the default behavior.
	if (_program == INTERSECT) {
		_splitBlockInfo->setAggregateAFraction(true);
	}
