bool NewChromSweep::intersects(const Record *rec1, const Record *rec2) const
{
    //return rec1->sameChromIntersects(rec2, _context->getSameStrand(), _context->getDiffStrand(),
    //        _context->getOverlapFraction(), _context->getReciprocal());
    float overlapFractionA = _context->getOverlapFractionA();
    float overlapFractionB = _context->getOverlapFractionB();
    // When obeying splits, the fraction of the (possibly discontinuous) A
    // record that overlaps is determined from its individual blocks by the
    // block overlap pass that runs after this coarse sweep. The sweep only has
    // the outer genomic span of each record, so the A fraction can not be
    // evaluated here; requiring any span overlap is sufficient to surface a
    // candidate, and the block pass applies the actual fraction. This keeps
    // split records consistent with the documented interval semantics instead
    // of silently dropping them because their span is long.
    if (_context->getObeySplits()) {
        overlapFractionA = 0.0f;
        overlapFractionB = 0.0f;
    }
    return rec1->sameChromIntersects(rec2,
                                     _context->getSameStrand(),
                                     _context->getDiffStrand(),
                                     overlapFractionA,
                                     overlapFractionB,
                                     _context->getReciprocalFraction(),
                                     _context->getEitherFraction());
}

